// 1. Suma al contador de producción semanal de Main (para los gráficos)
((Main)get_Main()).produccionSemanalActual += agent.cajasEquivalentes;

// 2. Suma las cajas terminadas al inventario físico de Lavandina (índice 0)
inventorySystem.get(0).inventory += agent.cajasEquivalentes;

// 3. Si hay clientes con pedidos atrasados (backlog), se despacha inmediatamente
double recovered = Math.min(inventorySystem.get(0).inventory, inventorySystem.get(0).backlog);
inventorySystem.get(0).inventory -= recovered;
inventorySystem.get(0).backlog -= recovered;

traceln("LAVANDINA DISPONIBLE: " + Math.round(inventorySystem.get(0).inventory) 
        + " | Backlog restante: " + Math.round(inventorySystem.get(0).backlog));

// 1. Suma al contador de producción semanal de Main (para los gráficos)
((Main)get_Main()).produccionSemanalActual += agent.cajasEquivalentes;

// 2. Identifica cuál de los 5 líquidos terminó e impacta su inventario correspondiente
for (ProductState ps : inventorySystem) {
    if (ps.product == agent.tipo) {
        ps.inventory += agent.cajasEquivalentes;

        // Satisface atrasos acumulados de ese producto si existen
        double recovered = Math.min(ps.inventory, ps.backlog);
        ps.inventory -= recovered;
        ps.backlog -= recovered;

        traceln("LIQUIDO TERMINADO: " + ps.product 
                + " | Stock: " + Math.round(ps.inventory) 
                + " | Backlog restante: " + Math.round(ps.backlog));
        break;
    }
}
